//! Schema of `effect_apply`.
use super::ToolSchema;

pub(crate) const FX_TOOLS: &[ToolSchema] = &[ToolSchema {
    name: "effect_apply",
    description: "Add an 80s-cartoon effect in ONE undoable edit: generates fragment markup plus animated tracks, or removes an earlier one. preset: speed_lines (mode radial|parallel, count 1-64, length, angle for parallel, seed, intensity, period = ticks per flicker frame, color), glow (blurred plus-lighter/screen copy of target: radius 0-32, intensity, pulse 0-1, period, blend), chromatic_split (red/blue channel offset copies of target: amount 0-64 px, angle, pulse, period), film_grain (feTurbulence soft-light overlay cycling frames 2-6 with different seeds: intensity, frequency, octaves 1-3, period, seed), halftone (rotated dot pattern whose dot radius animates dot -> dotTo as a fraction of size 2-64: angle, intensity, color), vhs_scanlines (line pattern with pitch 2-64, jitter 0-32 px, rolling bar, noise 0-1 grain), motion_blur_dir (trailing offset copies of target along angle: amount 0-64 px, copies 1-12, pulse, intensity), smear (squash-stretch tracks on target group over start..start+ticks: stretch 1-4, angle, attack, optional trail 0-8 copies spaced amount px; needs a target without another transform track), vignette (radial dark edge: intensity, softness 0-0.9, pulse, period, color), flash (colour pulse: intensity, attack and falloff ticks, color, blend). target: group or shape id (glow, chromatic_split, motion_blur_dir and smear act on it; the first three act on the whole scene when omitted; overlays are limited to its bounds when given and then need an untransformed target). start (default 0) and ticks (default to the last tick) bound the active ticks, which must be below the timeline duration. idPrefix (A-Z a-z 0-9 _ -, up to 48, default fx-<preset>-N) prefixes every generated element and track id and must be unused; remove: true with that idPrefix deletes everything the call generated (tracks, elements, scene grouping). Deterministic from seed; at most 256 generated elements. Example: {\"preset\":\"glow\",\"target\":\"sun\",\"radius\":10,\"intensity\":0.8}.",
    properties: "{\"documentId\":{\"type\":\"string\"},\"preset\":{\"type\":\"string\",\"enum\":[\"speed_lines\",\"glow\",\"chromatic_split\",\"film_grain\",\"halftone\",\"vhs_scanlines\",\"motion_blur_dir\",\"smear\",\"vignette\",\"flash\"]},\"target\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"idPrefix\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":48},\"remove\":{\"type\":\"boolean\"},\"start\":{\"type\":\"integer\",\"minimum\":0},\"ticks\":{\"type\":\"integer\",\"minimum\":1},\"seed\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":4294967295},\"count\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":64},\"length\":{\"type\":\"number\",\"minimum\":1,\"maximum\":4096},\"radius\":{\"type\":\"number\",\"minimum\":0,\"maximum\":32},\"amount\":{\"type\":\"number\",\"minimum\":0,\"maximum\":64},\"angle\":{\"type\":\"number\",\"minimum\":-360,\"maximum\":360},\"intensity\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"pulse\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"period\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000},\"size\":{\"type\":\"number\",\"minimum\":2,\"maximum\":64},\"dot\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"dotTo\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"pitch\":{\"type\":\"number\",\"minimum\":2,\"maximum\":64},\"jitter\":{\"type\":\"number\",\"minimum\":0,\"maximum\":32},\"noise\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"copies\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":12},\"stretch\":{\"type\":\"number\",\"minimum\":1,\"maximum\":4},\"trail\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":8},\"attack\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":48},\"falloff\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":480},\"frames\":{\"type\":\"integer\",\"minimum\":2,\"maximum\":6},\"frequency\":{\"type\":\"number\",\"minimum\":0.05,\"maximum\":4},\"octaves\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":3},\"softness\":{\"type\":\"number\",\"minimum\":0,\"maximum\":0.9},\"mode\":{\"type\":\"string\",\"enum\":[\"radial\",\"parallel\"]},\"color\":{\"type\":\"string\",\"maxLength\":7},\"blend\":{\"type\":\"string\",\"enum\":[\"normal\",\"screen\",\"plus-lighter\"]}}",
    required: "documentId,preset",
    fields: "documentId:string;preset:string;target:string;idPrefix:string;remove:boolean;start:integer;ticks:integer;seed:integer;count:integer;length:number;radius:number;amount:number;angle:number;intensity:number;pulse:number;period:integer;size:number;dot:number;dotTo:number;pitch:number;jitter:number;noise:number;copies:integer;stretch:number;trail:integer;attack:integer;falloff:integer;frames:integer;frequency:number;octaves:integer;softness:number;mode:string;color:string;blend:string",
}];
